INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b8f70a52-bd84-0c68-3cf4-08cafae64b91', 744817, 'DESCRIPTION', 'hotelInfo', 'en', 'description', 'With a stay at Babette Guldsmeden, you''ll be centrally located in Copenhagen, within a 5-minute drive of Tivoli Gardens and Strøget. This spa hotel is 0.7 mi (1.1 km) from Nyhavn and 1.6 mi (2.6 km) from City Hall Square.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9a640ef1-0203-1e4c-558d-7196ea43c879', 744817, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9a640ef1-0203-1e4c-558d-7196ea43c879', 744817, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p><strong>Check-in</strong> After 15:00</p><p><strong>Check-out</strong> Before 12:00</p><ul><li>Front desk hours: 24/7</li><li>The host or staff will greet you upon arrival</li><li>If you plan to arrive after 23:00 on your check-in day, contact the property in advance by email/phone</li></ul>');
