INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b8f70a52-bd84-0c68-3cf4-08cafae64b91', 744817, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Babette Guldsmeden ở trung tâm Copenhagen, cách Công viên Tivoli và Phố Strøget 5 phút lái xe. Khách sạn spa này cách Khu Nyhavn 1,1 km và cách Quảng trường Tòa thị chính 2,6 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9a640ef1-0203-1e4c-558d-7196ea43c879', 744817, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9a640ef1-0203-1e4c-558d-7196ea43c879', 744817, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> Trước 12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</li><li>Nếu bạn dự định sẽ đến sau 23:00 vào ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú qua email/điện thoại</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12a30eca-11b9-c1d1-414e-d1436581aab4', 744817, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12a30eca-11b9-c1d1-414e-d1436581aab4', 744817, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('760cd911-318b-e6b7-2fce-9e6934c92c40', 744817, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('760cd911-318b-e6b7-2fce-9e6934c92c40', 744817, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df67b48f-e598-0f4c-91a8-10fa7cb2f221', 744817, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
