INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04e6a449-e65b-9c89-3495-5f200e3080b5', 744866, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
