INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Comfort Hotel Vesterbro, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Phố Strøget 1,7 km và cách Torvehallerne 1,9 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 744866, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 744866, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04e6a449-e65b-9c89-3495-5f200e3080b5', 744866, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04e6a449-e65b-9c89-3495-5f200e3080b5', 744866, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('29667bdd-d9d9-bcf2-d66c-18703a157dd7', 744866, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('29667bdd-d9d9-bcf2-d66c-18703a157dd7', 744866, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05fdd019-8890-514f-9b74-df43e29c7943', 744866, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05fdd019-8890-514f-9b74-df43e29c7943', 744866, 'POLICY', 'breakfast', 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - CN] 07:30-11:00 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50f4a1b1-d3f7-4245-acad-ed71c88edc78', 744866, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
