INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ed83e035-2af1-9ca5-c0dc-0bae179cf7d4', 744868, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Good Morning City Copenhagen Star ở trung tâm Copenhagen, chỉ cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn này cách Phố Strøget 0,8 km và cách Khu Nyhavn 2,8 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('da54e32a-a545-4600-15f0-73150d0d2cf1', 744868, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('da54e32a-a545-4600-15f0-73150d0d2cf1', 744868, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> 04:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nếu bạn dự định sẽ đến sau 00:00 vào buổi sáng của ngày sau ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú</li></ul>');
