INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, 1 Hotel Copenhagen cách Khu phố Latin và Nhà thờ Đức Mẹ vài bước. Khách sạn sang trọng này cách Torvehallerne 0,4 km và cách Tháp thiên văn Round Tower 1,1 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 23:30</p><p><strong>Trả phòng</strong> 04:00–12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều có thể bổ sung cũi. Chính sách về giường phụ khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li><li>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f83b5169-d361-98d8-15d8-0dbc7b8c7735', 744872, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
