INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, AC Hotel by Marriott Bella Sky Copenhagen cách Sân vận động Royal 3 phút lái xe và cách Phố Strøget 7 phút lái xe. Khách sạn golf này cách Quảng trường Tòa thị chính 5,5 km và cách Công viên Tivoli 5,6 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 1863116, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 1863116, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('676960ce-13b0-58b9-80d3-e1012859e81d', 1863116, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
