INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c027cd60-9155-2917-f4c1-0d33904738e2', 2139197, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Coco Hotel chỉ cách Công viên Tivoli 8 phút đi bộ và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Sở thú Copenhagen 2,1 km và cách Lâu đài Rosenborg 2,4 km.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca7366ab-d366-dc62-f0b8-7d5c6f570706', 2139197, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca7366ab-d366-dc62-f0b8-7d5c6f570706', 2139197, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> 07:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nếu bạn dự định sẽ đến sau 00:00 vào buổi sáng của ngày sau ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cdbda098-dce5-eec4-9de7-9feef7230966', 2139197, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cdbda098-dce5-eec4-9de7-9feef7230966', 2139197, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('233ff2e4-4a4b-f972-2774-bb10f534fd1e', 2139197, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('233ff2e4-4a4b-f972-2774-bb10f534fd1e', 2139197, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li></ul>');
