INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e09f423-5163-c16e-08cd-ed800e04342b', 2150756, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Copenhagen Marriott Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e09f423-5163-c16e-08cd-ed800e04342b', 2150756, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Kalvebod Brygge 5, Indre By, Copenhagen, Hovedstaden, 1560, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e09f423-5163-c16e-08cd-ed800e04342b', 2150756, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e09f423-5163-c16e-08cd-ed800e04342b', 2150756, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '406');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e09f423-5163-c16e-08cd-ed800e04342b', 2150756, 'DESCRIPTION', 'hotelInfo', 'en', 'description', 'You''ll be centrally located in Copenhagen with a stay at Copenhagen Marriott Hotel, within a 15-minute walk of National Museum of Denmark and Tivoli Gardens. This luxury hotel is 0.5 mi (0.8 km) from Christiansborg Palace and 0.7 mi (1.1 km) from City Hall Square. Take advantage of recreational opportunities offered, including a sauna, a 24-hour fitness center, and bicycles to rent. Additional features at this hotel include complimentary wireless internet access, concierge services, and gift shops/newsstands. Grab a bite to eat at Pier 5, a waterfront bar/lounge, or stay in and take advantage of the 24-hour room service. Buffet breakfasts are available daily from 7:00 AM to 11:00 AM for a fee. Featured amenities include a 24-hour business center, car service, and express check-in. Planning an event in Copenhagen? This hotel has 9548 square feet (887 square meters) of space consisting of a conference center and meeting rooms. Make yourself at home in one of the guestrooms featuring minibars and LCD televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms with bathtubs or showers feature complimentary toiletries and hair dryers. Conveniences include phones, as well as safes and desks.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5e53cfde-5566-0c58-b5aa-3fc0dbd9c379', 2150756, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5e53cfde-5566-0c58-b5aa-3fc0dbd9c379', 2150756, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p><strong>Check-in</strong> After 16:00</p><p><strong>Check-out</strong> Before 12:00</p><ul><li>Front desk hours: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb758f5f-5d3c-5c5d-694f-c4fa72bf03c5', 2150756, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb758f5f-5d3c-5c5d-694f-c4fa72bf03c5', 2150756, 'POLICY', 'childPolicy', 'en', 'policy_content', '<ul><li>Children of all ages are welcome at this property.</li><li>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4892dbc-739f-db63-f6ae-7fd6cb86294a', 2150756, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4892dbc-739f-db63-f6ae-7fd6cb86294a', 2150756, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<ul><li>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</li></ul>');
