INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('adc40215-8cfc-4151-0f23-3e1b58be231a', 2159295, 'DESCRIPTION', 'hotelInfo', 'en', 'description', 'Historic waterfront hotel in central Copenhagen near Nyhavn and top attractions. Offers 366 renovated rooms- meeting facilities- sauna- bar- and outdoor cafe. In 2025- the newly renovated ground floor opened- featuring a new breakfast area and the vibrant restaurant aye aye. Ideal for business and leisure stays.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd5f7c84-809f-a599-0d49-a5f811e43e10', 2159295, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd5f7c84-809f-a599-0d49-a5f811e43e10', 2159295, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p><strong>Check-in</strong> 14:00–02:00 the next day</p><p><strong>Check-out</strong> Before 12:00</p><ul><li>Front desk hours: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc36c050-c18b-fe45-7fbd-89277406dc7f', 2159295, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc36c050-c18b-fe45-7fbd-89277406dc7f', 2159295, 'POLICY', 'childPolicy', 'en', 'policy_content', '<ul><li>Children of all ages are welcome at this property.</li><li>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 2159295, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 2159295, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<ul><li>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('104faa94-54e6-1221-107d-8f450819a8fb', 2159295, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
