INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df00f250-7c8b-00b3-9288-cce0fc89ab5f', 2195705, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
