INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> 00:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Tự nhận phòng: Liên lạc với chỗ nghỉ để được hướng dẫn cách lấy thẻ/chìa khóa</li><li>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd4b54a5-e42f-ab02-48e5-858f1b3e8d27', 3064270, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd4b54a5-e42f-ab02-48e5-858f1b3e8d27', 3064270, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'vi', 'policy_content', '<ul><li>Lựa chọn: Đồ ăn đóng hộp/gói</li><li>Ẩm thực: Đại lục</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
