INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd50c092-0ac4-586a-7ed0-4cd7eafd1e65', 48162461, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</li></ul>');
