INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d811cec0-f6a4-15f6-4aee-907ef39cc1ae', 76325348, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d811cec0-f6a4-15f6-4aee-907ef39cc1ae', 76325348, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee135d-db85-a2e5-e05b-8677472a71ec', 76325348, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee135d-db85-a2e5-e05b-8677472a71ec', 76325348, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('633ea54a-b5f5-4ebb-611a-e7feb0df7763', 76325348, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('633ea54a-b5f5-4ebb-611a-e7feb0df7763', 76325348, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5cf0022c-5c3a-d519-f919-d576f03cfea3', 76325348, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5cf0022c-5c3a-d519-f919-d576f03cfea3', 76325348, 'POLICY', 'breakfast', 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Ẩm thực: Đại lục, Không Gluten, Thuần chay, Chay</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fd15c9cc-383f-3dd2-c295-8d1f4a9186c6', 76325348, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
