INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('53fc808e-48e9-73fa-ca9d-1369a7d4c354', 83194466, 'POLICY', 'breakfast', 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
